def transform(grid):
    sep = next(c for c, v in enumerate(grid[0]) if v == 5)
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]

    # Overlay the right-hand pattern only when it does not collide
    # with any colored cells in the left-hand pattern.
    if any(left[r][c] and right[r][c]
           for r in range(len(grid))
           for c in range(len(left[0]))):
        return left

    return [
        [left[r][c] or right[r][c] for c in range(len(left[0]))]
        for r in range(len(grid))
    ]
